package com.hms.appointments;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/patients") public class PatientController {private final TenantRepository tenants;private final PatientRepository patients;public PatientController(TenantRepository t,PatientRepository p){tenants=t;patients=p;} @GetMapping("/{patientId}") public Patient get(@PathVariable String tenantSlug,@PathVariable UUID patientId){UUID tenant=tenant(tenantSlug);return patients.findById(patientId).filter(p->p.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Patient not found"));} @PutMapping("/{patientId}") public Patient update(@PathVariable String tenantSlug,@PathVariable UUID patientId,@Valid @RequestBody UpdatePatientRequest r){Patient patient=get(tenantSlug,patientId);patient.update(r);return patients.save(patient);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
